import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Matrix-SAVE-Command.md","filePath":"manual-en/Matrix-SAVE-Command.md","lastUpdated":1785684581000}'),s={name:"manual-en/Matrix-SAVE-Command.md"};function c(d,e,m,r,i,l){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h4 id="_16-4-10-the-save-command" tabindex="-1">16.4.10 The <code>SAVE</code> Command <a class="header-anchor" href="#_16-4-10-the-save-command" aria-label="Permalink to &quot;16.4.10 The \`SAVE\` Command&quot;">​</a></h4><pre><code>SAVE _expression_
     [/OUTFILE={_file_ _|_ *}]
     [/VARIABLES=_variable_ …]
     [/NAMES=_expression_]
     [/STRINGS=_variable_ …].
</code></pre><p>The <code>SAVE</code> matrix command evaluates <em>expression</em> and writes the resulting matrix to an SPSS system file. In the system file, each matrix row becomes a case and each column becomes a variable.</p><p>Specify the name or handle of the SPSS system file on the <code>OUTFILE</code> subcommand, or ‘*’ to write the output as the new active file. The <code>OUTFILE</code> subcommand is required on the first <code>SAVE</code> command, in syntax order, within <code>MATRIX</code>. For <code>SAVE</code> commands after the first, the default output file is the same as the previous.</p><p>When multiple <code>SAVE</code> commands write to one destination within a single <code>MATRIX</code>, the later commands append to the same output file. All the matrices written to the file must have the same number of columns. The <code>VARIABLES</code>, <code>NAMES</code>, and <code>STRINGS</code> subcommands are honored only for the first <code>SAVE</code> command that writes to a given file.</p><p>By default, <code>SAVE</code> names the variables in the output file <code>COL1</code> through <code>COL _n_</code>. Use <code>VARIABLES</code> or <code>NAMES</code> to give the variables meaningful names. The <code>VARIABLES</code> subcommand accepts a comma-separated list of variable names. Its alternative, <code>NAMES</code>, instead accepts an expression that must evaluate to a row or column string vector of names. The number of names need not exactly match the number of columns in the matrix to be written: extra names are ignored; extra columns use default names.</p><p>By default, <code>SAVE</code> assumes that the matrix to be written is all numeric. To write string columns, specify a comma-separated list of the string columns’ variable names on <code>STRINGS</code>.</p>`,7)])])}const p=a(s,[["render",c]]);export{u as __pageData,p as default};
